import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BeanDeserializerBase_deserializeFromString_TriageGen2Test {

    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private ValueInstantiator mockValueInstantiator;
    private JsonDeserializer<Object> mockDelegateDeserializer;
    private ObjectIdReader mockObjectIdReader;
    private BeanDeserializerBase beanDeserializerBase;

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockValueInstantiator = mock(ValueInstantiator.class);
        mockDelegateDeserializer = mock(JsonDeserializer.class);
        mockObjectIdReader = mock(ObjectIdReader.class);

        // Since BeanDeserializerBase is abstract, we use a mock or a concrete subclass.
        // We will use Mockito to create a spy of the abstract class to access protected fields via reflection if needed,
        // but here we will mock the behavior of the constructor-injected dependencies.
        beanDeserializerBase = mock(BeanDeserializerBase.class, withSettings()
                .useConstructor(mock(BeanDeserializerBuilder.class), 
                               mock(BeanDescription.class), 
                               mock(BeanPropertyMap.class), 
                               mock(Map.class), 
                               mock(Set.class), 
                               false, 
                               false)
                .defaultAnswer(CALLS_REAL_METHODS));
    }

    /**
     * Helper to inject protected fields into the mocked beanDeserializerBase
     */
    private void setField(String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = BeanDeserializerBase.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(beanDeserializerBase, value);
    }

    @Test
    public void testDeserializeFromString_WithObjectIdReader() throws Exception {
        setField("_objectIdReader", mockObjectIdReader);
        // We need to mock the call to deserializeFromObjectId which is a method in the class
        doReturn("objectIdResult").when(beanDeserializerBase).deserializeFromObjectId(mockParser, mockContext);

        Object result = beanDeserializerBase.deserializeFromString(mockParser, mockContext);

        assertEquals("objectIdResult", result);
        verify(beanDeserializerBase).deserializeFromObjectId(mockParser, mockContext);
    }

    @Test
    public void testDeserializeFromString_WithDelegateAndCanCreateFromStringTrue() throws Exception {
        setField("_objectIdReader", null);
        setField("_delegateDeserializer", mockDelegateDeserializer);
        setField("_valueInstantiator", mockValueInstantiator);
        setField("_injectables", null);

        when(mockValueInstantiator.canCreateFromString()).thenReturn(true);
        when(mockParser.getText()).thenReturn("stringVal");
        when(mockValueInstantiator.createFromString(mockContext, "stringVal")).thenReturn("createdObject");

        Object result = beanDeserializerBase.deserializeFromString(mockParser, mockContext);

        assertEquals("createdObject", result);
        verify(mockValueInstantiator).createFromString(mockContext, "stringVal");
        verify(mockDelegateDeserializer, never()).deserialize(any(), any());
    }

    @Test
    public void testDeserializeFromString_WithDelegateAndCanCreateFromStringFalse_NoInjectables() throws Exception {
        setField("_objectIdReader", null);
        setField("_delegateDeserializer", mockDelegateDeserializer);
        setField("_valueInstantiator", mockValueInstantiator);
        setField("_injectables", null);

        when(mockValueInstantiator.canCreateFromString()).thenReturn(false);
        when(mockDelegateDeserializer.deserialize(mockParser, mockContext)).thenReturn("delegateResult");
        when(mockValueInstantiator.createUsingDelegate(mockContext, "delegateResult")).thenReturn("beanWithDelegate");

        Object result = beanDeserializerBase.deserializeFromString(mockParser, mockContext);

        assertEquals("beanWithDelegate", result);
        verify(beanDeserializerBase, never()).injectValues(any(), any());
    }

    @Test
    public void testDeserializeFromString_WithDelegateAndCanCreateFromStringFalse_WithInjectables() throws Exception {
        setField("_objectIdReader", null);
        setField("_delegateDeserializer", mockDelegateDeserializer);
        setField("_valueInstantiator", mockValueInstantiator);
        setField("_injectables", Collections.singletonList(mock(InjectableValues.class)));

        when(mockValueInstantiator.canCreateFromString()).thenReturn(false);
        when(mockDelegateDeserializer.deserialize(mockParser, mockContext)).thenReturn("delegateResult");
        when(mockValueInstantiator.createUsingDelegate(mockContext, "delegateResult")).thenReturn("beanWithInject");

        Object result = beanDeserializerBase.deserializeFromString(mockParser, mockContext);

        assertEquals("beanWithInject", result);
        verify(beanDeserializerBase).injectValues(mockContext, "beanWithInject");
    }

    @Test
    public void testDeserializeFromString_DefaultPath() throws Exception {
        setField("_objectIdReader", null);
        setField("_delegateDeserializer", null);
        setField("_valueInstantiator", mockValueInstantiator);

        when(mockParser.getText()).thenReturn("plainString");
        when(mockValueInstantiator.createFromString(mockContext, "plainString")).thenReturn("plainObject");

        Object result = beanDeserializerBase.deserializeFromString(mockParser, mockContext);

        assertEquals("plainObject", result);
        verify(mockValueInstantiator).createFromString(mockContext, "plainString");
    }
}
